// Expand legacy tokens — module-level so mustRole and getBootstrap share one copy
function expandPages(pages) {
  if (!Array.isArray(pages)) return pages;
  const out = [...pages];
  // 'daily' or legacy 'production' token expands to all 5 production sub-pages
  if (out.includes('daily') || out.includes('production')) {
    for (const t of ['daily-timber', 'daily-poles', 'daily-harvest', 'value-added-production', 'machine-logs'])
      if (!out.includes(t)) out.push(t);
  }
  // Final Enterprise Completion Gate — found live: maintenanceOfficerDashboard/
  // maintenanceReports (data.js) both gate on 'maintenance-oversight', and
  // that's exactly what db/migrate.js grants to logistics/admin/ceo — but
  // the NAV entries for these two screens use different literal ids
  // ('maintenance-officer-dashboard'/'maintenance-reports'), which nothing
  // ever granted, so the fully-built, correctly-authorized screens had no
  // menu item any of those roles could click to reach them. Same expansion
  // idiom as 'daily' above — one permission unlocking its sub-pages,
  // additive only, no backend gate or migration change needed.
  if (out.includes('maintenance-oversight')) {
    for (const t of ['maintenance-officer-dashboard', 'maintenance-reports'])
      if (!out.includes(t)) out.push(t);
  }
  return out;
}

