async function stockMovementsDelete(userId, movementId, reason) {
  const user = await getUser(userId);
  if (!(await mustRole(user, 'stock-movements'))) return { ok: false, error: 'Access denied' };
  const { rows: snap } = await pool.query('SELECT * FROM stock_movements WHERE id=$1 AND deleted_at IS NULL', [movementId]);
  if (!snap.length) return { ok: false, error: 'Movement not found' };
  const before = snap[0];
  // ERP Stock & Inventory Phase 1 (Workstream 3) — had no Workshop Isolation
  // check at all, only the ownership/time-window governance below (which is
  // an orthogonal concern — a restricted user could otherwise delete/reverse
  // a movement belonging to a different workshop entirely, mutating that
  // other workshop's stock_levels). Standard isWorkshopRestricted idiom,
  // checked against both legs for the (retired, no-longer-creatable but
  // still-deletable) 'transfer' movement type.
  if (isWorkshopRestricted(user)) {
    const ownsSource = before.warehouse_id && Number(before.warehouse_id) === Number(user.workshop_id);
    const ownsDest = before.to_warehouse_id && Number(before.to_warehouse_id) === Number(user.workshop_id);
    if (!ownsSource && !ownsDest)
      return { ok: false, error: 'Access denied — this movement does not involve your workshop' };
  }
  const blocked = await applyGovernance(user, 'stock_movements', movementId, 'delete', {
    ownerCol: 'created_by', entityType: 'stock_movement',
    entityRef: `Stock movement #${movementId}`, before, reason
  });
  if (blocked) return blocked;
  const { item_id, warehouse_id, to_warehouse_id, movement_type, quantity } = before;
  // ERP Final Enterprise Completion Gate — real gap found: this reversed
  // stock_levels below but never logged the reversal itself as a
  // stock_movements row (only soft-deleted the original, which every ledger
  // query filters out via deleted_at is null) — so after a delete, the live
  // ledger showed neither the original event nor its reversal. Insert the
  // opposite-direction movement(s), same shape as every other real posting
  // in this file, so the ledger stays a complete record of what actually
  // happened to stock_levels.
  const revRef = `Reversal of stock movement #${movementId} — deleted`;
  const revNotes = reason || 'Movement moved to trash';
  // Reverse stock levels so inventory stays correct while record is in trash
  if (warehouse_id) {
    if (['in', 'return'].includes(movement_type)) {
      await pool.query(
        `update stock_levels set quantity=greatest(0,quantity-$1), updated_at=now()
         where item_id=$2 and warehouse_id=$3`,
        [quantity, item_id, warehouse_id]
      );
      await pool.query(
        `insert into stock_movements(item_id, warehouse_id, movement_type, quantity, reference, notes, created_by)
         values ($1,$2,'out',$3,$4,$5,$6)`,
        [item_id, warehouse_id, quantity, revRef, revNotes, user.id]
      );
    } else if (movement_type === 'out') {
      await pool.query(
        `update stock_levels set quantity=quantity+$1, updated_at=now()
         where item_id=$2 and warehouse_id=$3`,
        [quantity, item_id, warehouse_id]
      );
      await pool.query(
        `insert into stock_movements(item_id, warehouse_id, movement_type, quantity, reference, notes, created_by)
         values ($1,$2,'in',$3,$4,$5,$6)`,
        [item_id, warehouse_id, quantity, revRef, revNotes, user.id]
      );
    } else if (movement_type === 'transfer' && to_warehouse_id) {
      await pool.query(
        `update stock_levels set quantity=quantity+$1, updated_at=now() where item_id=$2 and warehouse_id=$3`,
        [quantity, item_id, warehouse_id]
      );
      await pool.query(
        `update stock_levels set quantity=greatest(0,quantity-$1), updated_at=now() where item_id=$2 and warehouse_id=$3`,
        [quantity, item_id, to_warehouse_id]
      );
      await pool.query(
        `insert into stock_movements(item_id, warehouse_id, movement_type, quantity, reference, notes, created_by)
         values ($1,$2,'in',$3,$4,$5,$6)`,
        [item_id, warehouse_id, quantity, revRef, revNotes, user.id]
      );
      await pool.query(
        `insert into stock_movements(item_id, warehouse_id, movement_type, quantity, reference, notes, created_by)
         values ($1,$2,'out',$3,$4,$5,$6)`,
        [item_id, to_warehouse_id, quantity, revRef, revNotes, user.id]
      );
    }
  }
  await pool.query(
    'update stock_movements set deleted_at=now(), deleted_by=$1, deletion_reason=$2, pending_deletion=false where id=$3',
    [user.id, reason || null, movementId]
  );
  logAudit(user, `Moved stock movement #${movementId} (${movement_type}) to trash`, 'ti-trash', { movementId, reason },
    { module: 'stock_movements', actionType: 'delete', recordId: movementId, before, reason });
  return { ok: true };
}

// Stock & Inventory Phase 4 (audit finding H-10) — warehousesDelete had no
// usage guard at all: any stock_movements/stock_transfers row referencing
// this warehouse (via FK) made the delete throw a raw, ungraceful Postgres
// constraint-violation error instead of a controlled message; if no FK
// happened to be enforced for a given reference, deleting a warehouse with
// real stock_levels history would silently orphan it. Mirrors
// _stockItemUsageCount/stockItemsDelete's own already-established guard
// pattern exactly, checking the same kinds of real usage a warehouse can
// have: nonzero current stock, movement/transfer history, and material
// requests targeting it as a workshop.
async function _warehouseUsageCount(warehouseId) {
  const { rows } = await pool.query(
    `select
       (select count(*) from stock_levels where warehouse_id=$1 and coalesce(quantity,0) > 0) +
       (select count(*) from stock_movements where warehouse_id=$1 or to_warehouse_id=$1) +
       (select count(*) from stock_transfers where from_warehouse_id=$1 or to_warehouse_id=$1) +
       (select count(*) from material_requests where workshop_id=$1)
       as n`,
    [warehouseId]
  );
  return Number(rows[0]?.n || 0);
}

