async function financeStockCountDetail(userId, sessionId) {
  const user = await getUser(userId);
  if (!(await _canAccessFinanceStockCount(user))) return { ok: false, error: 'Access denied' };
  const { rows: [session] } = await pool.query(
    `select s.*, w.name as workshop_name, u.name as initiated_by_name from stock_count_sessions s
     left join warehouses w on w.id=s.workshop_id left join app_users u on u.id=s.initiated_by
     where s.id=$1`, [sessionId]
  );
  if (!session) return { ok: false, error: 'Stock count session not found' };
  if (isWorkshopRestricted(user) && session.workshop_id && Number(session.workshop_id) !== Number(user.workshop_id))
    return { ok: false, error: 'Access denied — this stock count does not belong to your workshop' };
  const { rows: lines } = await pool.query(
    `select l.*, sc.name as item_name, sc.category, sc.uom,
            (l.physical_qty - l.system_qty_snapshot) as variance,
            ((l.physical_qty - l.system_qty_snapshot) * coalesce(l.unit_cost_snapshot,0))::numeric as financial_variance
     from stock_count_lines l join stock_catalog sc on sc.id=l.item_id
     where l.session_id=$1 order by sc.name`, [sessionId]
  );
  return { ok: true, session, lines };
}

async function financeStockCountEnterCount(userId, sessionId, lineId, physicalQty, notes) {
  const user = await getUser(userId);
  if (!(await _canAccessFinanceStockCount(user))) return { ok: false, error: 'Access denied' };
  const qty = Number(physicalQty);
  if (!Number.isFinite(qty) || qty < 0) return { ok: false, error: 'Physical quantity must be zero or greater' };
  const { rows: [session] } = await pool.query('select * from stock_count_sessions where id=$1', [sessionId]);
  if (!session) return { ok: false, error: 'Stock count session not found' };
  if (!['draft', 'counting'].includes(session.status)) return { ok: false, error: `Cannot enter counts — session is ${session.status}` };
  if (isWorkshopRestricted(user) && session.workshop_id && Number(session.workshop_id) !== Number(user.workshop_id))
    return { ok: false, error: 'Access denied — this stock count does not belong to your workshop' };
  const { rows } = await pool.query(
    `update stock_count_lines set physical_qty=$1, notes=$2, status='counted', counted_by=$3, counted_at=now()
     where id=$4 and session_id=$5 returning id`,
    [qty, notes || null, user.id, lineId, sessionId]
  );
  if (!rows.length) return { ok: false, error: 'Stock count line not found' };
  return { ok: true };
}

async function financeStockCountSubmitForReview(userId, sessionId) {
  const user = await getUser(userId);
  if (!(await _canAccessFinanceStockCount(user))) return { ok: false, error: 'Access denied' };
  const { rows: [session] } = await pool.query('select * from stock_count_sessions where id=$1', [sessionId]);
  if (!session) return { ok: false, error: 'Stock count session not found' };
  if (isWorkshopRestricted(user) && session.workshop_id && Number(session.workshop_id) !== Number(user.workshop_id))
    return { ok: false, error: 'Access denied' };
  if (!['draft', 'counting'].includes(session.status)) return { ok: false, error: `Cannot submit — session is ${session.status}` };
  const { rows: uncounted } = await pool.query(
    `select count(*)::int as n from stock_count_lines where session_id=$1 and physical_qty is null`, [sessionId]);
  if (uncounted[0].n > 0)
    return { ok: false, error: `${uncounted[0].n} item(s) still uncounted — count every line before submitting for review.` };
  await pool.query(`update stock_count_sessions set status='pending_review' where id=$1`, [sessionId]);
  logAudit(user, `Submitted stock count #${sessionId} for review`, 'ti-clipboard-check', {},
    { workshopId: session?.workshop_id, module: 'finance', actionType: 'stock_count_submit', recordId: sessionId });
  return { ok: true };
}

// Every nonzero-variance line becomes a real governed adjustment request
// (never a direct stock_levels write); zero-variance lines are simply marked
// reviewed so the session reaches a clean completed state. Re-running this
// on an already-completed session is a no-op (skips lines that already have
// an adjustment_request_id), making it safe against duplicate submission.
async function financeStockCountSubmitAdjustments(userId, sessionId, reason) {
  const user = await getUser(userId);
  if (!(await _canAccessFinanceStockCount(user))) return { ok: false, error: 'Access denied' };
  const { rows: [session] } = await pool.query('select * from stock_count_sessions where id=$1', [sessionId]);
  if (!session) return { ok: false, error: 'Stock count session not found' };
  if (isWorkshopRestricted(user) && session.workshop_id && Number(session.workshop_id) !== Number(user.workshop_id))
    return { ok: false, error: 'Access denied' };
  if (session.status !== 'pending_review')
    return { ok: false, error: `Cannot submit adjustments — session is ${session.status}, expected pending_review` };

  // Atomically claim the session before doing any work — two concurrent
  // calls (e.g. a double-click, or two finance users acting on the same
  // session) would otherwise both pass the status check above and both
  // loop over the same variance lines, each creating its own duplicate
  // pending_edits request before either finished writing
  // adjustment_request_id back. This UPDATE...WHERE is the actual
  // concurrency-safe guard — only one caller's UPDATE can match
  // status='pending_review' at a time; the loser sees 0 rows affected and
  // bails immediately instead of racing.
  const { rowCount: claimed } = await pool.query(
    `update stock_count_sessions set status='submitted' where id=$1 and status='pending_review'`, [sessionId]
  );
  if (!claimed) return { ok: false, error: 'This stock count is already being submitted or was already completed.' };

  const { rows: varianceLines } = await pool.query(
    `select l.*, sc.name as item_name from stock_count_lines l join stock_catalog sc on sc.id=l.item_id
     where l.session_id=$1 and l.physical_qty is not null and l.physical_qty != l.system_qty_snapshot and l.adjustment_request_id is null`,
    [sessionId]
  );
  let submitted = 0;
  for (const line of varianceLines) {
    const result = await _stockAdjustmentRequestSubmit(user, {
      item_id: line.item_id, warehouse_id: session.workshop_id, quantity: line.physical_qty,
      reference: `Stock Count #${sessionId}`,
      reason: (reason && reason.trim()) || `Physical stock count #${sessionId} variance for ${line.item_name}`,
    }, { module: 'finance', actionType: 'stock_count_adjustment_request' });
    if (result.ok) {
      await pool.query(`update stock_count_lines set adjustment_request_id=$1, status='reviewed' where id=$2`, [result.id, line.id]);
      submitted++;
    }
  }
  await pool.query(
    `update stock_count_lines set status='reviewed' where session_id=$1 and physical_qty = system_qty_snapshot and status != 'reviewed'`,
    [sessionId]
  );
  await pool.query(`update stock_count_sessions set status='completed', completed_at=now() where id=$1`, [sessionId]);
  logAudit(user, `Completed stock count #${sessionId} — ${submitted} adjustment request(s) submitted`, 'ti-check',
    { submitted }, { workshopId: session?.workshop_id, module: 'finance', actionType: 'stock_count_complete', recordId: sessionId });
  return { ok: true, submitted, varianceLineCount: varianceLines.length };
}

async function financeStockCountCancel(userId, sessionId, reason) {
  const user = await getUser(userId);
  if (!(await _canAccessFinanceStockCount(user))) return { ok: false, error: 'Access denied' };
  const { rows: [session] } = await pool.query('select * from stock_count_sessions where id=$1', [sessionId]);
  if (!session) return { ok: false, error: 'Stock count session not found' };
  if (isWorkshopRestricted(user) && session.workshop_id && Number(session.workshop_id) !== Number(user.workshop_id))
    return { ok: false, error: 'Access denied' };
  if (['completed', 'cancelled'].includes(session.status))
    return { ok: false, error: `Cannot cancel — session is already ${session.status}` };
  await pool.query(
    `update stock_count_sessions set status='cancelled', notes=coalesce(notes,'') || $2 where id=$1`,
    [sessionId, reason ? `\n[Cancelled] ${reason}` : '\n[Cancelled]']
  );
  logAudit(user, `Cancelled stock count #${sessionId}`, 'ti-x', { reason },
    { workshopId: session?.workshop_id, module: 'finance', actionType: 'stock_count_cancel', recordId: sessionId });
  return { ok: true };
}

// ── Stock Variance Control ──────────────────────────────────────────────────
// Highlights per Section 9: large/repeated variances, negative stock,
// high-value discrepancies — derived entirely from completed count lines
// plus a live stock_levels check, never auto-corrected here (view →
// investigate → approve/audit only, via the Exception Center below).
async function financeStockVarianceReport(userId, filters) {
  const user = await getUser(userId);
  if (!(await _canAccessFinance(user))) return { ok: false, error: 'Access denied' };
  const restricted = isWorkshopRestricted(user);
  const f = filters || {};
  const wId = restricted ? user.workshop_id : (f.workshop_id ? Number(f.workshop_id) : null);
  const conds = [`l.physical_qty is not null`, `l.physical_qty != l.system_qty_snapshot`];
  const params = [];
  if (wId) { params.push(wId); conds.push(`s.workshop_id = $${params.length}`); }
  if (f.date_from) { params.push(f.date_from); conds.push(`s.initiated_at >= $${params.length}`); }
  if (f.date_to) { params.push(f.date_to); conds.push(`s.initiated_at <= $${params.length}`); }
  const { rows } = await pool.query(
    `select l.id as line_id, l.session_id, s.workshop_id, w.name as workshop_name, sc.id as item_id, sc.name as item_name,
            l.system_qty_snapshot, l.physical_qty, (l.physical_qty - l.system_qty_snapshot) as variance,
            case when l.system_qty_snapshot > 0
              then round(((l.physical_qty - l.system_qty_snapshot)::numeric / l.system_qty_snapshot) * 100, 1)
              else null end as variance_pct,
            ((l.physical_qty - l.system_qty_snapshot) * coalesce(l.unit_cost_snapshot,0))::numeric as financial_variance,
            l.adjustment_request_id, s.initiated_at
     from stock_count_lines l
     join stock_count_sessions s on s.id = l.session_id
     join stock_catalog sc on sc.id = l.item_id
     left join warehouses w on w.id = s.workshop_id
     where ${conds.join(' and ')}
     order by abs((l.physical_qty - l.system_qty_snapshot) * coalesce(l.unit_cost_snapshot,0)) desc
     limit 300`,
    params
  );
  const byItem = {};
  rows.forEach(r => { byItem[r.item_id] = (byItem[r.item_id] || 0) + 1; });
  const repeatedItemIds = new Set(Object.entries(byItem).filter(([, n]) => n > 1).map(([itemId]) => Number(itemId)));

  const { rows: negativeStock } = await pool.query(
    `select sl.item_id, sc.name as item_name, sl.warehouse_id, w.name as workshop_name, sl.quantity
     from stock_levels sl join stock_catalog sc on sc.id=sl.item_id left join warehouses w on w.id=sl.warehouse_id
     where sl.quantity < 0 ${wId ? 'and sl.warehouse_id=$1' : ''}`,
    wId ? [wId] : []
  );

  const HIGH_VALUE_THRESHOLD = 50000;
  return {
    ok: true,
    rows: rows.map(r => ({ ...r, repeated: repeatedItemIds.has(Number(r.item_id)) })),
    negativeStock,
    highValueThreshold: HIGH_VALUE_THRESHOLD,
    highValueCount: rows.filter(r => Math.abs(Number(r.financial_variance)) >= HIGH_VALUE_THRESHOLD).length,
  };
}

