// ║  SECTION 2 — RISK DETECTION FUNCTIONS                                       ║
// ╚══════════════════════════════════════════════════════════════════════════════╝

function _biDetectFuelAnomalies(fuelData) {
  const { z_score, pct_change, recent_7d_avg, mean, data_points } = fuelData;
  const z   = Number(z_score)   || 0;
  const pct = Number(pct_change)|| 0;
  const detected  = z > 1.5;
  const severity  = z > 2 ? 'critical' : z > 1.5 ? 'high' : z > 0.8 ? 'medium' : 'low';
  const score     = z > 2 ? 40 : z > 1.5 ? 25 : z > 0.8 ? 10 : 0;
  const description = (data_points || 0) < 5
    ? 'Insufficient fuel data for anomaly detection'
    : detected
    ? `Fuel consumption ${Math.abs(pct).toFixed(1)}% ${pct > 0 ? 'above' : 'below'} baseline (Z=${z.toFixed(2)})`
    : `Fuel consumption within normal range (Z=${z.toFixed(2)})`;
  return {
    detected, z_score: z, pct_change: pct,
    recent_avg: Number(recent_7d_avg) || 0,
    baseline:   Number(mean)          || 0,
    score, severity, description,
    metrics: { z_score: z, pct_change: pct, data_points: data_points || 0 },
  };
}

async function _biDetectStockAnomalies() {
  const { rows } = await pool.query(`
    WITH stats AS (
      SELECT item_id,
             AVG(ABS(quantity))::numeric              AS mean_qty,
             COALESCE(STDDEV_POP(ABS(quantity)), 0)::numeric AS stddev_qty
      FROM stock_movements
      WHERE created_at >= NOW() - INTERVAL '60 days'
        AND deleted_at IS NULL
      GROUP BY item_id
    )
    SELECT sm.item_id, sm.quantity, sm.movement_type,
           sm.created_at::text AS created_at,
           sc.name             AS item_name,
           ROUND(((ABS(sm.quantity) - s.mean_qty)
             / NULLIF(s.stddev_qty, 0))::numeric, 2) AS z_score
    FROM stock_movements sm
    JOIN stock_catalog  sc ON sc.id = sm.item_id
    JOIN stats          s  ON s.item_id = sm.item_id
    WHERE sm.created_at >= NOW() - INTERVAL '7 days'
      AND sm.deleted_at IS NULL
      AND s.stddev_qty > 0
      AND ABS(sm.quantity) > s.mean_qty + 2 * s.stddev_qty
    ORDER BY z_score DESC NULLS LAST
    LIMIT 10`);

  const maxZ     = rows.length ? Math.max(...rows.map(r => Number(r.z_score) || 0)) : 0;
  const severity = rows.length >= 5 || maxZ > 4 ? 'critical'
    : rows.length >= 2 || maxZ > 3 ? 'high'
    : rows.length >= 1 ? 'medium' : 'low';
  return {
    anomalies:   rows,
    count:       rows.length,
    score:       Math.min(rows.length * 10, 40),
    severity,
    description: rows.length
      ? `${rows.length} abnormal stock movement(s) in last 7 days`
      : 'No abnormal stock movements detected',
    metrics: { count: rows.length, max_z_score: maxZ },
  };
}

async function _biDetectMachineEfficiency() {
  const { rows } = await pool.query(`
    WITH weekly_eff AS (
      SELECT machine_id,
             ROW_NUMBER() OVER (PARTITION BY machine_id ORDER BY DATE_TRUNC('week', log_date)) - 1 AS x,
             AVG(CASE WHEN capacity_per_day > 0
               THEN daily_production::numeric / capacity_per_day * 100 END)::numeric AS eff
      FROM machine_daily_logs
      WHERE log_date >= CURRENT_DATE - 63
        AND deleted_at IS NULL
      GROUP BY machine_id, DATE_TRUNC('week', log_date)
    )
    SELECT m.machine_code, m.name,
           ROUND(regr_slope(eff, x)::numeric, 2)  AS eff_slope,
           ROUND(AVG(eff)::numeric, 1)             AS avg_eff,
           COUNT(*)::int                           AS weeks
    FROM weekly_eff we
    JOIN machines m ON m.id = we.machine_id
    WHERE we.eff IS NOT NULL
    GROUP BY m.id, m.machine_code, m.name
    HAVING COUNT(*) >= 3 AND regr_slope(eff, x) < -2
    ORDER BY regr_slope(eff, x) ASC
    LIMIT 8`);

  const severity = rows.some(r => Number(r.eff_slope) < -10) ? 'critical'
    : rows.length > 2 ? 'high' : rows.length > 0 ? 'medium' : 'low';
  return {
    declining:   rows,
    count:       rows.length,
    score:       Math.min(rows.length * 15, 45),
    severity,
    description: rows.length
      ? `${rows.length} machine(s) with declining weekly efficiency`
      : 'No significant efficiency decline detected',
    metrics: { count: rows.length },
  };
}

async function _biDetectDelayedDeliveries() {
  const { rows } = await pool.query(`
    SELECT id, order_number, delivery_date::text,
           (CURRENT_DATE - delivery_date)::int AS days_overdue,
           status, driver_name
    FROM delivery_orders
    WHERE status IN ('Pending', 'Dispatched')
      AND delivery_date < CURRENT_DATE
    ORDER BY days_overdue DESC
    LIMIT 20`);

  const maxOverdue = rows.length ? Math.max(...rows.map(r => Number(r.days_overdue))) : 0;
  const severity   = maxOverdue > 7 || rows.length > 5 ? 'critical'
    : maxOverdue > 3 || rows.length > 2 ? 'high'
    : rows.length > 0 ? 'medium' : 'low';
  return {
    items:       rows,
    count:       rows.length,
    score:       Math.min(rows.length * 10, 40),
    severity,
    description: rows.length
      ? `${rows.length} delivery order(s) past due (max ${maxOverdue} day(s) overdue)`
      : 'All deliveries on schedule',
    metrics: { count: rows.length, max_days_overdue: maxOverdue },
  };
}

async function _biDetectSecurityRisks() {
  const { rows } = await pool.query(`
    SELECT
      (SELECT COUNT(*)::int FROM audit_log
       WHERE action_type = 'login_failed'
         AND created_at > NOW() - INTERVAL '24 hours') AS failed_logins_24h,
      (SELECT COUNT(DISTINCT user_id)::int FROM audit_log
       WHERE action_type = 'login_failed'
         AND created_at > NOW() - INTERVAL '24 hours') AS unique_users_failed,
      (SELECT COUNT(*)::int FROM audit_log
       WHERE action_type = 'login_failed'
         AND created_at > NOW() - INTERVAL '1 hour')   AS failed_logins_1h`);

  const r   = rows[0] || {};
  const fl  = Number(r.failed_logins_24h)  || 0;
  const uu  = Number(r.unique_users_failed) || 0;
  const h1  = Number(r.failed_logins_1h)   || 0;
  const brute   = h1 >= 5 || (fl >= 10 && uu <= 2);
  const severity = brute || fl >= 20 ? 'critical' : fl >= 10 ? 'high' : fl >= 3 ? 'medium' : 'low';
  return {
    failed_logins_24h:     fl,
    unique_users_failed:   uu,
    failed_logins_1h:      h1,
    brute_force_suspected: brute,
    score:       brute ? 50 : Math.min(fl * 2, 30),
    severity,
    description: brute
      ? `Possible brute-force: ${h1} failures in 1h (${fl} total 24h)`
      : fl >= 3 ? `${fl} failed login attempt(s) in last 24h`
      : 'No unusual login activity',
    metrics: { failed_logins_24h: fl, unique_users_failed: uu, failed_logins_1h: h1 },
  };
}

async function _biDetectGovernanceRisks() {
  const [gRes, slaRes] = await Promise.all([
    pool.query(`
      SELECT
        (SELECT COUNT(*)::int FROM audit_log
         WHERE action_type = 'privileged_override'
           AND created_at > NOW() - INTERVAL '24 hours')            AS priv_overrides_24h,
        (SELECT COUNT(*)::int FROM pending_edits
         WHERE status = 'Pending'
           AND submitted_at < NOW() - INTERVAL '48 hours')          AS stalled_48h,
        (SELECT COUNT(*)::int FROM pending_edits
         WHERE status = 'Pending'
           AND submitted_at < NOW() - INTERVAL '96 hours')          AS stalled_96h,
        (SELECT COUNT(*)::int FROM pending_edits WHERE status='Pending') +
        (SELECT COUNT(*)::int FROM deletion_requests WHERE status='pending') AS total_pending,
        (SELECT ROUND(AVG(EXTRACT(EPOCH FROM (NOW() - submitted_at))/3600)::numeric, 1)
         FROM pending_edits WHERE status = 'Pending')               AS avg_pending_hours`),
    pool.query(`
      SELECT ROUND(
        100.0 * COUNT(CASE WHEN EXTRACT(EPOCH FROM (reviewed_at - submitted_at)) <= 172800 THEN 1 END)
        / NULLIF(COUNT(id), 0), 1)::numeric AS sla_pct
      FROM pending_edits
      WHERE status IN ('Approved','Rejected')
        AND submitted_at >= NOW() - INTERVAL '30 days'`),
  ]);

  const g   = gRes.rows[0]   || {};
  const s   = slaRes.rows[0] || {};
  const ov  = Number(g.priv_overrides_24h) || 0;
  const s48 = Number(g.stalled_48h)        || 0;
  const s96 = Number(g.stalled_96h)        || 0;
  const tp  = Number(g.total_pending)      || 0;
  const aph = Number(g.avg_pending_hours)  || 0;
  const sla = Number(s.sla_pct)            ?? 100;

  const severity = (ov > 3 || s96 > 0 || sla < 50) ? 'critical'
    : (ov > 0 || s48 > 3 || sla < 70) ? 'high'
    : (s48 > 0 || sla < 90) ? 'medium' : 'low';
  return {
    priv_overrides_24h: ov,
    stalled_48h:        s48,
    stalled_96h:        s96,
    total_pending:      tp,
    avg_pending_hours:  aph,
    sla_compliance_pct: sla,
    score: Math.min(ov * 10 + s48 * 5 + Math.max(0, 100 - sla), 50),
    severity,
    description: ov > 0
      ? `${ov} privileged override(s) in 24h; ${s48} stalled approval(s)`
      : s48 > 0 ? `${s48} approval(s) pending over 48h (SLA: ${sla}%)`
      : `Governance healthy — SLA: ${sla}%`,
    metrics: { priv_overrides_24h: ov, stalled_48h: s48, total_pending: tp, sla_compliance_pct: sla },
  };
}

async function _biDetectWorkflowRisks() {
  const { rows } = await pool.query(`
    SELECT
      COUNT(*) FILTER (WHERE status = 'failed')::int                        AS failed_jobs,
      COUNT(*) FILTER (WHERE status = 'processing'
        AND created_at < NOW() - INTERVAL '30 minutes')::int                AS stuck_processing,
      COUNT(*) FILTER (WHERE status = 'pending')::int                       AS pending_jobs,
      COUNT(*)::int                                                         AS total_jobs
    FROM workflow_jobs`);

  const r  = rows[0] || {};
  const fj = Number(r.failed_jobs)      || 0;
  const sp = Number(r.stuck_processing) || 0;
  const severity = fj > 10 || sp > 0 ? 'critical' : fj > 5 ? 'high' : fj > 0 ? 'medium' : 'low';
  return {
    failed_jobs:      fj,
    stuck_processing: sp,
    pending_jobs:     Number(r.pending_jobs) || 0,
    score:            Math.min(fj * 5 + sp * 20, 60),
    severity,
    description:      sp > 0 ? `${sp} job(s) stuck in processing; ${fj} failed`
      : fj > 0 ? `${fj} failed workflow job(s) need attention`
      : 'All workflow jobs healthy',
    metrics: { failed_jobs: fj, stuck_processing: sp },
  };
}

// ╔══════════════════════════════════════════════════════════════════════════════╗
// ║  SECTION 3 — SYNTHESIS FUNCTIONS                                            ║
// ╚══════════════════════════════════════════════════════════════════════════════╝

function _biGenerateRecommendations(predictions, detections) {
  const SEV_ORDER = { critical: 0, high: 1, medium: 2, low: 3 };
  const recs  = [];
  let   _seq  = 0;
  const addR  = (sev, icon, mod, text, action = '') =>
    recs.push({ id: `bi-rec-${++_seq}`, title: text.slice(0, 60),
      description: text, priority: sev, module: mod, action, icon });

  const { stockRunout, harvest, production, sales, maintenance } = predictions;
  const { fuelAnomaly, machineEfficiency, delayedDeliveries,
          security, governance, workflow } = detections;

  // Stock shortages
  for (const s of (stockRunout || []).filter(r => r.days_until_depletion != null && r.days_until_depletion <= 7).slice(0, 3))
    addR('critical', 'ti-package', 'Stock',
      `"${s.name}" will run out in ${s.days_until_depletion} day(s) — reorder immediately.`,
      'Raise a material request now');
  const hs = (stockRunout || []).filter(r => r.days_until_depletion != null && r.days_until_depletion > 7 && r.days_until_depletion <= 14);
  if (hs.length)
    addR('high', 'ti-package', 'Stock',
      `${hs.length} stock item(s) will deplete within 14 days.`,
      'Review procurement schedule');

  // Maintenance
  for (const m of (maintenance || []).filter(r => Number(r.days_overdue) > 0).slice(0, 3))
    addR(Number(m.days_overdue) > 14 ? 'critical' : 'high',
      'ti-settings-2', 'Machines',
      `Machine "${m.machine_code} ${m.name}" — ${m.maintenance_type} is ${m.days_overdue} day(s) overdue.`,
      'Schedule maintenance immediately');

  // Fuel anomaly
  if (fuelAnomaly && fuelAnomaly.detected) {
    const fp = fuelAnomaly.pct_change || 0;
    addR(fuelAnomaly.severity, 'ti-droplet', 'Fuel',
      fp > 0
        ? `Fuel up ${Math.abs(fp).toFixed(1)}% vs baseline — investigate abnormal usage.`
        : `Fuel down ${Math.abs(fp).toFixed(1)}% — verify machines are running normally.`,
      fp > 0 ? 'Audit fuel logs and check for leaks' : 'Confirm machines are operational');
  }

  // Sales trend
  if (sales && sales.trend.avg_daily > 0) {
    const tp = (sales.trend.slope / sales.trend.avg_daily) * 100;
    if (tp > 5)
      addR('low', 'ti-trending-up', 'Sales',
        `Sales trending up +${tp.toFixed(1)}%/day — consider increasing production capacity.`,
        'Review production capacity plan');
    else if (tp < -5)
      addR('medium', 'ti-trending-down', 'Sales',
        `Sales declining ${Math.abs(tp).toFixed(1)}%/day — review pricing and customer retention.`,
        'Conduct customer and pricing review');
  }

  // Production trend
  if (production && production.trend.total_avg > 0) {
    const pt = (production.trend.total_slope / production.trend.total_avg) * 100;
    if (pt < -10)
      addR('high', 'ti-building-factory', 'Production',
        `Workshop output dropped ${Math.abs(pt).toFixed(0)}%/week — check downtime and machine efficiency.`,
        'Audit production downtime logs');
    else if (pt > 10)
      addR('low', 'ti-trending-up', 'Production',
        `Workshop output up ${pt.toFixed(0)}%/week — strong output trend continues.`,
        'Maintain current operational pace');
  }

  // Slow harvests
  for (const h of (harvest || []).filter(r => r.days_to_complete !== null && r.days_to_complete > 90))
    addR('medium', 'ti-trees', 'Harvest',
      `Compartment "${h.compt_name}" — est. ${h.days_to_complete} more days at current pace.`,
      'Review harvest scheduling and resource allocation');

  // Declining machine efficiency
  for (const m of (machineEfficiency?.declining || []).slice(0, 2))
    addR('high', 'ti-settings-2', 'Machines',
      `Machine "${m.machine_code} ${m.name}" efficiency declining ${Math.abs(Number(m.eff_slope)).toFixed(1)}%/week.`,
      'Schedule preventive inspection');

  // Approvals
  if (governance && governance.stalled_48h > 0)
    addR('medium', 'ti-clock-check', 'Approvals',
      `${governance.stalled_48h} approval request(s) pending over 48h — SLA breached.`,
      'Escalate to senior approver');
  if (governance && governance.priv_overrides_24h > 0)
    addR(governance.priv_overrides_24h > 3 ? 'critical' : 'high',
      'ti-shield-exclamation', 'Governance',
      `${governance.priv_overrides_24h} privileged override(s) used in last 24h.`,
      'Review override justifications in audit log');

  // Security
  if (security && security.brute_force_suspected)
    addR('critical', 'ti-lock', 'Security',
      `Possible brute-force: ${security.failed_logins_1h} failed logins in 1h.`,
      'Consider temporary lockout or IP restriction');
  else if (security && security.failed_logins_24h >= 10)
    addR('high', 'ti-lock', 'Security',
      `${security.failed_logins_24h} failed login attempts in last 24h.`,
      'Review audit log and notify affected users');

  // Workflow jobs
  if (workflow && workflow.stuck_processing > 0)
    addR('critical', 'ti-alert-triangle', 'System',
      `${workflow.stuck_processing} workflow job(s) stuck in processing — system may be stalled.`,
      'Run workflow recovery: recoverWorkflowState()');
  else if (workflow && workflow.failed_jobs > 0)
    addR(workflow.failed_jobs > 5 ? 'critical' : 'high',
      'ti-alert-triangle', 'System',
      `${workflow.failed_jobs} failed workflow job(s) detected.`,
      'Review workflow_jobs table for error details');

  // Delayed deliveries
  if (delayedDeliveries && delayedDeliveries.count > 0)
    addR(delayedDeliveries.severity, 'ti-truck', 'Logistics',
      `${delayedDeliveries.count} delivery order(s) are past their due date.`,
      'Contact drivers and update delivery status');

  recs.sort((a, b) => SEV_ORDER[a.priority] - SEV_ORDER[b.priority]);
  return recs;
}

function calculateCompanyHealth(predictions, detections, config = {}) {
  const pen      = { ...BI_HEALTH_PENALTIES, ...config };
  let   score    = 100;
  const breakdown = [];

  const sub = (label, raw, icon) => {
    const pts = Math.max(0, Math.min(Math.round(raw), 25));
    if (pts > 0) breakdown.push({ label, pts, icon, deduction: pts });
    score -= pts;
  };

  const { stockRunout, maintenance }  = predictions;
  const { workflow, governance, security,
          fuelAnomaly, delayedDeliveries, machineEfficiency } = detections;

  sub('Failed Workflow Jobs',
    (workflow.failed_jobs + workflow.stuck_processing * 2) * pen.failedJob,
    'ti-alert-triangle');
  sub('Failed Logins (24h)',
    security.failed_logins_24h * pen.failedLogin,
    'ti-lock');
  sub('Pending Approvals',
    Math.min(governance.total_pending * pen.pendingApproval, 15),
    'ti-clock');
  sub('Stalled Approvals (>48h)',
    governance.stalled_48h * pen.stalledApproval,
    'ti-clock-off');
  sub('Near-Depletion Stock',
    (stockRunout || []).length * pen.lowStockItem,
    'ti-package');
  sub('Delayed Deliveries',
    delayedDeliveries.count * pen.delayedDelivery,
    'ti-truck');
  sub('Overdue Maintenance',
    (maintenance || []).filter(m => Number(m.days_overdue) > 0).length * pen.overdueMaintenance,
    'ti-settings-2');
  sub('Governance Overrides (24h)',
    governance.priv_overrides_24h * pen.govOverride,
    'ti-shield-exclamation');
  sub('Declining Machine Efficiency',
    (machineEfficiency?.declining || []).length * pen.decliningMachine,
    'ti-trending-down');
  sub('Fuel Anomaly',
    fuelAnomaly.detected
      ? (fuelAnomaly.z_score > 2 ? pen.fuelAnomaly_high : pen.fuelAnomaly_med) : 0,
    'ti-droplet');

  score = Math.max(0, Math.round(score));
  const grade = score >= 80 ? 'Excellent' : score >= 60 ? 'Good' : score >= 40 ? 'Warning' : 'Critical';
  return { score, grade, breakdown };
}

// ── Main orchestrator (exported, same API surface as Phase 7) ─────────────────
const BI_SECTIONS = {
  admin:                   ['health','stock','fuel','machines','workshop','harvest','sales','governance','recommendations','charts'],
  ceo:                     ['health','stock','fuel','machines','workshop','harvest','sales','governance','recommendations','charts'],
  operations:              ['health','stock','fuel','machines','workshop','harvest','sales','governance','recommendations','charts'],
  supervisor:              ['health','stock','fuel','machines','workshop','harvest','recommendations','charts'],
  'sawmill-leader':        ['health','fuel','machines','workshop'],
  'sawmill-supervisor':    ['health','fuel','machines','workshop'],
  'harvesting-leader':     ['health','fuel','harvest'],
  'harvesting-supervisor': ['health','fuel','harvest'],
  'vat-leader':            ['health','workshop','harvest'],
  'poles-leader':          ['health','machines','harvest'],
  storekeeper:             ['health','stock','fuel'],
  'storekeeper-assistant': ['health','stock'],
};

async function businessIntelligenceDashboard(userId) {
  const user     = await getUser(userId);
  const sections = BI_SECTIONS[user.role];
  if (!sections)
    return { ok: false, error: 'Access denied' };

  const [
    sales,
    fuelRaw,
    stockRunout,
    harvest,
    production,
    maintenance,
    stockAnomalyDet,
    machineEfficiency,
    delayedDeliveries,
    security,
    governance,
    workflow,
  ] = await Promise.all([
    _biPredictSales(),
    _biPredictFuelConsumption(),
    _biPredictStockRunout(),
    _biPredictHarvestCompletion(),
    _biPredictWorkshopProduction(),
    _biPredictMaintenance(),
    _biDetectStockAnomalies(),
    _biDetectMachineEfficiency(),
    _biDetectDelayedDeliveries(),
    _biDetectSecurityRisks(),
    _biDetectGovernanceRisks(),
    _biDetectWorkflowRisks(),
  ]);

  const fuelAnomaly    = _biDetectFuelAnomalies(fuelRaw);
  const allPredictions = { stockRunout, fuel: fuelRaw, harvest, production, sales, maintenance };
  const allDetections  = {
    fuelAnomaly, stockAnomalies: stockAnomalyDet,
    machineEfficiency, delayedDeliveries, security, governance, workflow,
  };

  const recommendations = _biGenerateRecommendations(allPredictions, allDetections);
  const health          = calculateCompanyHealth(allPredictions, allDetections);

  // Build sorted risk list from all detections
  const SEV_ORDER = { critical: 0, high: 1, medium: 2, low: 3 };
  const risks     = [];
  const addRisk   = (severity, module, title, detail, icon) =>
    risks.push({ severity, module, title, detail, icon });

  for (const item of stockRunout) {
    const d   = item.days_until_depletion;
    const sev = d != null ? (d <= 7 ? 'critical' : d <= 14 ? 'high' : 'medium') : 'medium';
    addRisk(sev, 'Stock', `Shortage: ${item.name}`,
      d != null ? `${d} day(s) until depletion` : 'Below minimum stock', 'ti-package');
  }
  if (fuelAnomaly.detected)
    addRisk(fuelAnomaly.severity, 'Fuel', 'Fuel Consumption Anomaly',
      fuelAnomaly.description, 'ti-droplet');
  for (const m of maintenance) {
    const ov = Number(m.days_overdue);
    addRisk(ov > 14 ? 'critical' : ov > 0 ? 'high' : 'medium', 'Machines',
      `Maintenance: ${m.machine_code}`,
      ov > 0 ? `${m.maintenance_type} — ${ov} day(s) overdue`
             : `${m.maintenance_type} due within 14 days`, 'ti-settings-2');
  }
  for (const m of machineEfficiency.declining)
    addRisk('high', 'Machines', `Declining Efficiency: ${m.machine_code}`,
      `${Math.abs(Number(m.eff_slope)).toFixed(1)}%/week decline`, 'ti-trending-down');
  if (security.failed_logins_24h >= 3)
    addRisk(security.severity, 'Security',
      security.brute_force_suspected ? 'Possible Brute-Force Attack' : 'Multiple Failed Logins',
      security.description, 'ti-lock');
  if (governance.priv_overrides_24h > 0)
    addRisk(governance.priv_overrides_24h > 3 ? 'critical' : 'high', 'Governance',
      'Privileged Override Activity',
      `${governance.priv_overrides_24h} override(s) in 24h`, 'ti-shield-exclamation');
  if (governance.stalled_48h > 0)
    addRisk(governance.stalled_48h > 5 ? 'high' : 'medium', 'Approvals',
      'Stalled Approval Requests',
      `${governance.stalled_48h} request(s) pending > 48h`, 'ti-clock-off');
  if (delayedDeliveries.count > 0)
    addRisk(delayedDeliveries.severity, 'Logistics', 'Delayed Deliveries',
      `${delayedDeliveries.count} delivery order(s) past due`, 'ti-truck');
  if (workflow.failed_jobs > 0)
    addRisk(workflow.severity, 'System', 'Failed Workflow Jobs',
      `${workflow.failed_jobs} job(s) in failed state`, 'ti-alert-triangle');
  for (const sm of stockAnomalyDet.anomalies)
    addRisk(Number(sm.z_score) > 3 ? 'critical' : 'high', 'Stock',
      `Abnormal Movement: ${sm.item_name}`,
      `Qty ${sm.quantity} (${sm.movement_type}) — ${Number(sm.z_score).toFixed(1)}σ from mean`,
      'ti-arrows-exchange');
  risks.sort((a, b) => SEV_ORDER[a.severity] - SEV_ORDER[b.severity]);

  // govRisk summary — keeps the same renderer API shape from Phase 7
  const govRow = {
    failed_logins_24h:  security.failed_logins_24h,
    priv_overrides_24h: governance.priv_overrides_24h,
    failed_jobs:        workflow.failed_jobs,
    total_pending:      governance.total_pending,
    stalled_48h:        governance.stalled_48h,
    delayed_deliveries: delayedDeliveries.count,
    avg_pending_hours:  governance.avg_pending_hours,
  };

  return {
    ok: true,
    sections,
    health,
    predictions: {
      stockShortages:     stockRunout,
      fuelAnomaly:        { ...fuelRaw, z_score: fuelAnomaly.z_score, pct_change: fuelAnomaly.pct_change },
      machineAlerts:      maintenance,
      efficiencyDecline:  machineEfficiency.declining,
      harvestForecast:    harvest,
      salesRegression:    sales.trend,
      workshopRegression: production.trend,
    },
    forecasts: {
      sales30d:      sales.history,
      salesForecast: sales.forecast,
      wkTrend:       production.history,
      wkForecast:    production.forecast,
    },
    risks,
    recommendations,
    govRisk:        govRow,
    stockAnomalies: stockAnomalyDet.anomalies,
  };
}

// ── Global Search ─────────────────────────────────────────────────────────────
// Cross-module search. Every branch is normalized to
// (module, id, title, subtitle, description, status, created_at) and combined with
// UNION ALL, so results across every permitted module are ranked/paginated together
// in a single round trip. Shared bind params (fixed positions, referenced selectively
// per branch — unreferenced params are simply ignored by pg):
//   $1 contains-pattern ("%term%")   $5 createdBy name pattern ("%name%")
//   $2 workshop id (or null)         $6 starts-with pattern ("term%") — relevance sort
//   $3 status filter (or null)       $7 current user id
//   $4 department filter (or null)   $8 current user role
const SEARCH_OVERVIEW_CAP = 6;

const REPORT_ENTRIES = [
  { key: 'weekly-perf',   label: 'Weekly Performance Report',       description: 'Weekly production and KPI performance summary', page: 'weekly-perf' },
  { key: 'weekly-cost',   label: 'Weekly Cost Report',              description: 'Weekly expense and cost breakdown',              page: 'weekly-cost' },
  { key: 'executive',     label: 'Executive Dashboard',             description: 'Company-wide executive analytics and risk overview', page: 'executive' },
  { key: 'bi',            label: 'Business Intelligence Dashboard', description: 'Predictive analytics and anomaly detection',     page: 'bi' },
  { key: 'epm',           label: 'Enterprise Performance Dashboard',description: 'Department scorecards and performance KPIs',     page: 'epm' },
  { key: 'ceo-overview',  label: 'CEO Overview',                    description: 'Company-wide executive summary',                 page: 'ceo' },
  { key: 'sales-dashboard', label: 'Sales Dashboard & History',     description: 'Revenue, order status, top products, and filterable Sales History with CSV export', page: 'sales-dashboard' },
];

const SEARCH_MODULE_ROUTE = {
  sales: 'SalesOrders', deliveries: 'Deliveries', dispatch: 'Dispatch',
  stock_transfers: 'StockTransfers', inventory: 'Inventory', timber: 'Timber',
  poles: 'Poles', workshop: 'Workshop', machines: 'Machines', fuel: 'Fuel',
  material_requests: 'MaterialRequests', purchase_requests: 'PurchaseRequests',
  labour: 'Labour', production: 'Production', reports: 'Reports',
  customers: 'Customers', products: 'Products', vehicles: 'Vehicles',
  users: 'Users', audit_logs: 'AuditLogs', change_requests: 'ChangeRequests',
  notifications: 'Notifications',
};

function _searchModules(user) {
  const changeReqTierPe = MANAGER_APPROVERS.includes(user.role) ? '1=1'
    : LEADER_APPROVERS.includes(user.role) ? `pe.required_level = 'leader'`
    : `pe.submitted_by = $7`;
  const changeReqTierDr = MANAGER_APPROVERS.includes(user.role) ? '1=1'
    : LEADER_APPROVERS.includes(user.role) ? `dr2.required_level = 'leader'`
    : `dr2.requested_by = $7`;

  return [
    {
      key: 'sales', label: 'Sales Orders',
      canAccess: (u) => mustRole(u, 'sales'),
      sql: `select 'sales' as module, so.id, so.order_number as title,
                   coalesce(c.name, so.customer_name) as subtitle,
                   trim(so.product_type || ' ' || coalesce(so.product_sub_type,'') || ' ' || coalesce(so.product_size,'')) as description,
                   so.status, so.created_at
            from sales_orders so
            left join customers c  on c.id = so.customer_id
            left join app_users cu on cu.id = so.created_by
            where so.deleted_at is null
              and ($2::bigint is null or so.workshop_id = $2 or so.workshop_id is null)
              and ($3::text is null or so.status = $3)
              and ($5::text is null or unaccent(cu.name) ilike unaccent($5))
              and (unaccent(so.order_number) ilike unaccent($1) or unaccent(so.customer_name) ilike unaccent($1)
                   or unaccent(coalesce(c.name,'')) ilike unaccent($1) or unaccent(coalesce(c.phone,'')) ilike unaccent($1)
                   or unaccent(coalesce(so.product_size,'')) ilike unaccent($1) or unaccent(coalesce(so.notes,'')) ilike unaccent($1))`,
    },
    {
      key: 'deliveries', label: 'Deliveries',
      canAccess: (u) => mustRole(u, 'deliveries'),
      sql: `select 'deliveries' as module, do2.id, do2.order_number as title,
                   do2.driver_name as subtitle,
                   coalesce(so.customer_name, v.registration) as description,
                   do2.status, do2.created_at
            from delivery_orders do2
            left join vehicles v      on v.id = do2.vehicle_id
            left join sales_orders so on so.id = do2.sales_order_id
            left join app_users cu    on cu.id = do2.created_by
            where do2.deleted_at is null
              and ($3::text is null or do2.status = $3)
              and ($5::text is null or unaccent(cu.name) ilike unaccent($5))
              and (unaccent(do2.order_number) ilike unaccent($1) or unaccent(coalesce(do2.driver_name,'')) ilike unaccent($1)
                   or unaccent(coalesce(v.registration,'')) ilike unaccent($1) or unaccent(coalesce(so.order_number,'')) ilike unaccent($1)
                   or unaccent(coalesce(so.customer_name,'')) ilike unaccent($1) or unaccent(coalesce(do2.notes,'')) ilike unaccent($1))`,
    },
    {
      key: 'dispatch', label: 'Dispatch',
      canAccess: (u) => mustRole(u, 'dispatch'),
      sql: `select 'dispatch' as module, dr.id, dr.request_number as title,
                   do2.driver_name as subtitle,
                   coalesce(so.customer_name, v.registration) as description,
                   dr.status, dr.created_at
            from dispatch_requests dr
            left join delivery_orders do2 on do2.id = dr.delivery_order_id
            left join sales_orders so     on so.id = do2.sales_order_id
            left join vehicles v          on v.id = do2.vehicle_id
            left join app_users cu        on cu.id = dr.created_by
            where dr.deleted_at is null
              and ($3::text is null or dr.status = $3)
              and ($5::text is null or unaccent(cu.name) ilike unaccent($5))
              and (unaccent(dr.request_number) ilike unaccent($1) or unaccent(coalesce(do2.driver_name,'')) ilike unaccent($1)
                   or unaccent(coalesce(v.registration,'')) ilike unaccent($1) or unaccent(coalesce(so.order_number,'')) ilike unaccent($1)
                   or unaccent(coalesce(so.customer_name,'')) ilike unaccent($1) or unaccent(coalesce(dr.notes,'')) ilike unaccent($1))`,
    },
    {
      key: 'stock_transfers', label: 'Stock Transfers',
      canAccess: (u) => mustRole(u, 'stock-transfers'),
      sql: `select 'stock_transfers' as module, st.id,
                   coalesce(st.reference, 'Transfer #' || st.id) as title,
                   sc.name as subtitle,
                   fw.name || ' → ' || tw.name as description,
                   st.status, st.requested_at as created_at
            from stock_transfers st
            join stock_catalog sc  on sc.id = st.item_id
            join warehouses fw     on fw.id = st.from_warehouse_id
            join warehouses tw     on tw.id = st.to_warehouse_id
            left join app_users cu on cu.id = st.requested_by
            where st.deleted_at is null
              and ($2::bigint is null or st.from_warehouse_id = $2 or st.to_warehouse_id = $2)
              and ($3::text is null or st.status = $3)
              and ($5::text is null or unaccent(cu.name) ilike unaccent($5))
              and (unaccent(sc.name) ilike unaccent($1) or unaccent(coalesce(st.reference,'')) ilike unaccent($1)
                   or unaccent(coalesce(st.notes,'')) ilike unaccent($1) or unaccent(fw.name) ilike unaccent($1) or unaccent(tw.name) ilike unaccent($1))`,
    },
    {
      key: 'inventory', label: 'Inventory',
      canAccess: (u) => mustRole(u, 'stock-items'),
      sql: `select 'inventory' as module, sc.id, sc.name as title, sc.category as subtitle,
                   sc.sku as description,
                   case when sc.active then 'Active' else 'Inactive' end as status,
                   sc.created_at
            from stock_catalog sc
            where sc.active = true
              and ($2::bigint is null or exists (
                    select 1 from stock_levels sl where sl.item_id = sc.id and sl.warehouse_id = $2))
              and (unaccent(sc.name) ilike unaccent($1) or unaccent(sc.category) ilike unaccent($1)
                   or unaccent(coalesce(sc.sku,'')) ilike unaccent($1))`,
    },
    {
      key: 'timber', label: 'Timber',
      // Harvesting Phase 1 (Workstream 6) — this only checked 'harvest',
      // narrower than dailyHarvestData's own gate ('daily-harvest' or
      // 'harvest' or 'daily'), the function that actually powers the live
      // Harvest page both platforms use. ceo/harvesting-supervisor hold
      // 'daily-harvest' but not 'harvest' (db/migrate.js) and could view
      // harvest records everywhere else but not find them via Global Search.
      canAccess: async (u) => (await mustRole(u, 'harvest')) || (await mustRole(u, 'daily-harvest')),
      sql: `select 'timber' as module, hl.id, hl.species as title, hl.location as subtitle,
                   hl.notes as description, null::text as status, hl.created_at
            from harvest_logs hl
            where hl.deleted_at is null
              and ($2::bigint is null or hl.workshop_id = $2 or hl.workshop_id is null)
              and (unaccent(hl.species) ilike unaccent($1) or unaccent(coalesce(hl.location,'')) ilike unaccent($1)
                   or unaccent(coalesce(hl.notes,'')) ilike unaccent($1))`,
    },
    {
      key: 'poles', label: 'Poles',
      canAccess: (u) => canAccessDaily(u),
      sql: `select 'poles' as module, pd.id, coalesce(pd.delivery_note_ref, 'Delivery #' || pd.id) as title,
                   pd.supplier_name as subtitle, (pd.delivered_qty || ' poles') as description,
                   pd.status, pd.created_at
            from poles_deliveries pd
            where ($2::bigint is null or pd.workshop_id = $2)
              and ($3::text is null or pd.status = $3)
              and (unaccent(coalesce(pd.supplier_name,'')) ilike unaccent($1) or unaccent(coalesce(pd.delivery_note_ref,'')) ilike unaccent($1)
                   or unaccent(coalesce(pd.notes,'')) ilike unaccent($1))`,
    },
    {
      key: 'purchase_requests', label: 'Purchase Requests',
      canAccess: (u) => canAccessDaily(u),
      sql: `select 'purchase_requests' as module, pr.id, pr.supplier_name as title,
                   (pr.requested_qty || ' requested') as subtitle, pr.notes as description,
                   pr.status, pr.requested_at as created_at
            from poles_purchase_requests pr
            where ($2::bigint is null or pr.workshop_id = $2)
              and ($3::text is null or pr.status = $3)
              and (unaccent(pr.supplier_name) ilike unaccent($1) or unaccent(coalesce(pr.notes,'')) ilike unaccent($1))`,
    },
    {
      key: 'workshop', label: 'Workshop',
      canAccess: (u) => mustRole(u, 'warehouses'),
      sql: `select 'workshop' as module, w.id, w.name as title, w.location as subtitle,
                   w.workshop_type as description,
                   case when w.active then 'Active' else 'Inactive' end as status, w.created_at
            from warehouses w
            where unaccent(w.name) ilike unaccent($1) or unaccent(coalesce(w.location,'')) ilike unaccent($1)`,
    },
    {
      key: 'machines', label: 'Machines',
      canAccess: async (u) => (await mustRole(u, 'machines')) || (await mustRole(u, 'machine-logs')) || (await mustRole(u, 'machine-kpi')),
      sql: `select 'machines' as module, m.id, m.name as title, m.machine_code as subtitle,
                   mc.name as description, m.status, m.created_at
            from machines m
            join machine_categories mc on mc.id = m.category_id
            left join app_users cu     on cu.id = m.created_by
            where m.active = true
              and ($2::bigint is null or m.workshop_id = $2 or m.workshop_id is null)
              and ($3::text is null or m.status = $3)
              and ($5::text is null or unaccent(cu.name) ilike unaccent($5))
              and (unaccent(m.name) ilike unaccent($1) or unaccent(m.machine_code) ilike unaccent($1)
                   or unaccent(coalesce(m.plate_number,'')) ilike unaccent($1) or unaccent(coalesce(m.notes,'')) ilike unaccent($1))`,
    },
    {
      key: 'fuel', label: 'Fuel',
      canAccess: async (u) => (await mustRole(u, 'machine-fuel')) || ['admin','ceo','operations','logistics','supervisor'].includes(u.role),
      sql: `select 'fuel' as module, mfl.id, coalesce(m.name, v.registration) as title,
                   mfl.fuel_type as subtitle, (mfl.quantity || ' ' || mfl.unit) as description,
                   null::text as status, mfl.log_date::timestamptz as created_at
            from machine_fuel_logs mfl
            left join machines m on m.id = mfl.machine_id
            left join vehicles v on v.id = mfl.vehicle_id
            where mfl.deleted_at is null
              and (unaccent(coalesce(mfl.operator,'')) ilike unaccent($1) or unaccent(mfl.fuel_type) ilike unaccent($1)
                   or unaccent(coalesce(mfl.notes,'')) ilike unaccent($1) or unaccent(coalesce(m.name,'')) ilike unaccent($1)
                   or unaccent(coalesce(v.registration,'')) ilike unaccent($1))`,
    },
    {
      key: 'material_requests', label: 'Material Requests',
      canAccess: (u) => mustRole(u, 'stock-movements'),
      sql: `select 'material_requests' as module, mr.id, sc.name as title, w.name as subtitle,
                   mr.reason as description, mr.status, mr.requested_at as created_at
            from material_requests mr
            join stock_catalog sc  on sc.id = mr.item_id
            left join warehouses w on w.id = mr.workshop_id
            left join app_users cu on cu.id = mr.requested_by
            where ($2::bigint is null or mr.workshop_id = $2)
              and ($3::text is null or mr.status = $3)
              and ($5::text is null or unaccent(cu.name) ilike unaccent($5))
              and (unaccent(sc.name) ilike unaccent($1) or unaccent(coalesce(mr.reason,'')) ilike unaccent($1))`,
    },
    {
      key: 'labour', label: 'Labour',
      canAccess: async (u) => (await mustRole(u, 'casual-requests')) || ['admin','ceo','operations','supervisor'].includes(u.role),
      sql: `select 'labour' as module, clr.id, clr.task as title,
                   (clr.num_casuals || ' casuals') as subtitle, clr.description, clr.status, clr.created_at
            from casual_labour_requests clr
            where ($2::bigint is null or clr.workshop_id = $2 or clr.workshop_id is null)
              and ($3::text is null or clr.status = $3)
              and (unaccent(clr.task) ilike unaccent($1) or unaccent(coalesce(clr.description,'')) ilike unaccent($1)
                   or unaccent(coalesce(clr.comments,'')) ilike unaccent($1))`,
    },
    {
      key: 'labour', label: 'Labour',
      canAccess: async (u) => (await mustRole(u, 'casuals')) || ['admin','ceo','operations','supervisor'].includes(u.role),
      sql: `select 'labour' as module, c.id, c.full_name as title, c.job_role as subtitle,
                   c.department as description,
                   case when c.active then 'Active' else 'Inactive' end as status, c.created_at
            from casuals c
            where ($2::bigint is null or c.workshop_id = $2 or c.workshop_id is null)
              and ($4::text is null or unaccent(c.department) ilike unaccent($4))
              and (unaccent(c.full_name) ilike unaccent($1) or unaccent(coalesce(c.phone,'')) ilike unaccent($1)
                   or unaccent(coalesce(c.department,'')) ilike unaccent($1) or unaccent(coalesce(c.job_role,'')) ilike unaccent($1))`,
    },
    {
      key: 'production', label: 'Production',
      canAccess: (u) => canAccessDaily(u),
      sql: `select 'production' as module, dl.id,
                   ('Daily log — ' || to_char(dl.log_date,'DD Mon YYYY')) as title,
                   dl.supervisor as subtitle, dl.remarks as description,
                   null::text as status, dl.log_date::timestamptz as created_at
            from daily_logs dl
            where dl.deleted_at is null
              and ($2::bigint is null or dl.workshop_id = $2 or dl.workshop_id is null)
              and (unaccent(coalesce(dl.supervisor,'')) ilike unaccent($1) or unaccent(coalesce(dl.operators,'')) ilike unaccent($1)
                   or unaccent(coalesce(dl.remarks,'')) ilike unaccent($1) or unaccent(coalesce(dl.machine,'')) ilike unaccent($1)
                   or unaccent(coalesce(dl.product_size,'')) ilike unaccent($1))`,
    },
    {
      key: 'customers', label: 'Customers',
      canAccess: (u) => mustRole(u, 'customers'),
      sql: `select 'customers' as module, c.id, c.name as title, c.phone as subtitle,
                   c.contact_person as description,
                   case when c.active then 'Active' else 'Inactive' end as status, c.created_at
            from customers c
            left join app_users cu on cu.id = c.created_by
            where ($5::text is null or unaccent(cu.name) ilike unaccent($5))
              and (unaccent(c.name) ilike unaccent($1) or unaccent(coalesce(c.contact_person,'')) ilike unaccent($1)
                   or unaccent(coalesce(c.phone,'')) ilike unaccent($1) or unaccent(coalesce(c.email,'')) ilike unaccent($1)
                   or unaccent(coalesce(c.tin,'')) ilike unaccent($1) or unaccent(coalesce(c.notes,'')) ilike unaccent($1))`,
    },
    {
      key: 'products', label: 'Products',
      canAccess: (u) => mustRole(u, 'products'),
      sql: `select 'products' as module, p.id,
                   trim(coalesce(p.sub_type, p.type) || ' ' || p.size) as title,
                   p.type as subtitle, p.machine as description,
                   case when p.active then 'Active' else 'Inactive' end as status, p.created_at
            from products p
            where (unaccent(p.type) ilike unaccent($1) or unaccent(coalesce(p.sub_type,'')) ilike unaccent($1)
                   or unaccent(p.size) ilike unaccent($1) or unaccent(coalesce(p.machine,'')) ilike unaccent($1)
                   or unaccent(coalesce(p.ref,'')) ilike unaccent($1))`,
    },
    {
      key: 'vehicles', label: 'Vehicles',
      canAccess: (u) => mustRole(u, 'vehicles'),
      sql: `select 'vehicles' as module, v.id, v.registration as title,
                   trim(coalesce(v.make,'') || ' ' || coalesce(v.model,'')) as subtitle,
                   v.driver_name as description, v.status, v.created_at
            from vehicles v
            where ($3::text is null or v.status = $3)
              and ($4::text is null or unaccent(coalesce(v.department,'')) ilike unaccent($4))
              and (unaccent(v.registration) ilike unaccent($1) or unaccent(coalesce(v.make,'')) ilike unaccent($1)
                   or unaccent(coalesce(v.model,'')) ilike unaccent($1) or unaccent(coalesce(v.driver_name,'')) ilike unaccent($1)
                   or unaccent(coalesce(v.driver_phone,'')) ilike unaccent($1) or unaccent(coalesce(v.asset_code,'')) ilike unaccent($1))`,
    },
    {
      key: 'users', label: 'Users',
      canAccess: (u) => u.role === 'admin',
      sql: `select 'users' as module, u.id, u.name as title, u.username as subtitle,
                   u.department as description,
                   case when u.active then 'Active' else 'Inactive' end as status, u.created_at
            from app_users u
            where u.deleted_at is null
              and ($2::bigint is null or u.workshop_id = $2)
              and (unaccent(u.name) ilike unaccent($1) or unaccent(u.username) ilike unaccent($1)
                   or unaccent(coalesce(u.department,'')) ilike unaccent($1))`,
    },
    {
      key: 'audit_logs', label: 'Audit Logs',
      canAccess: (u) => u.role === 'admin',
      sql: `select 'audit_logs' as module, a.id, a.action as title,
                   coalesce(a.full_name, a.username) as subtitle, a.module as description,
                   a.action_type as status, a.created_at
            from audit_log a
            where (unaccent(a.action) ilike unaccent($1) or unaccent(coalesce(a.username,'')) ilike unaccent($1)
                   or unaccent(coalesce(a.full_name,'')) ilike unaccent($1) or unaccent(coalesce(a.module,'')) ilike unaccent($1))`,
    },
    {
      key: 'change_requests', label: 'Change Requests',
      canAccess: () => true, // visibility is tiered per-row below, not a flat page gate
      sql: `select 'change_requests' as module, pe.id,
                   coalesce(pe.entity_ref, pe.entity_type || ' #' || pe.entity_id) as title,
                   pe.action_type as subtitle, pe.entity_type as description, pe.status, pe.submitted_at as created_at
            from pending_edits pe
            where ${changeReqTierPe}
              and ($3::text is null or pe.status = $3)
              and (unaccent(coalesce(pe.entity_ref,'')) ilike unaccent($1) or unaccent(pe.entity_type) ilike unaccent($1)
                   or unaccent(pe.action_type) ilike unaccent($1))`,
    },
    {
      key: 'change_requests', label: 'Change Requests',
      canAccess: () => true,
      sql: `select 'change_requests' as module, dr2.id,
                   coalesce(dr2.entity_ref, dr2.entity_type || ' #' || dr2.record_id) as title,
                   'Deletion request' as subtitle, dr2.deletion_reason as description, dr2.status,
                   dr2.requested_at as created_at
            from deletion_requests dr2
            where ${changeReqTierDr}
              and ($3::text is null or dr2.status = $3)
              and (unaccent(coalesce(dr2.entity_ref,'')) ilike unaccent($1) or unaccent(dr2.entity_type) ilike unaccent($1)
                   or unaccent(coalesce(dr2.deletion_reason,'')) ilike unaccent($1))`,
    },
    {
      key: 'notifications', label: 'Notifications',
      canAccess: (u) => mustRole(u, 'notifications'),
      sql: `select 'notifications' as module, n.id, n.title, n.category as subtitle,
                   n.body as description, n.type as status, n.created_at
            from notifications n
            where (
                    (array_length(n.roles,1) is null or n.roles = '{}' or $8 = any(n.roles))
                    or n.for_user_id = $7
                  )
              and (unaccent(n.title) ilike unaccent($1) or unaccent(n.body) ilike unaccent($1))`,
    },
  ];
}

async function globalSearch(userId, filters = {}) {
  const user = await getUser(userId);
  const q = String(filters.q || '').trim();
  // A module scope with no query text is a "browse this module" request (e.g. a
  // suggested-module chip tapped before typing) — only short-circuit empty/short
  // queries when there's no module to browse. `%${q}%` with q='' becomes '%%',
  // which ILIKE-matches every non-null row on its own — no per-branch SQL change
  // needed for browse mode to just work.
  if (q.length < 2 && !filters.module) return { ok: true, total: 0, moduleCounts: {}, results: [] };

  const wId = isWorkshopRestricted(user)
    ? user.workshop_id
    : (filters.workshop ? Number(filters.workshop) : null);

  const allModules = _searchModules(user);
  const moduleFilter = filters.module || null;
  const candidates = moduleFilter ? allModules.filter(m => m.key === moduleFilter) : allModules;

  const permitted = [];
  for (const mod of candidates) {
    if (await mod.canAccess(user)) permitted.push(mod);
  }

  const reportBranches = (!moduleFilter || moduleFilter === 'reports')
    ? await Promise.all(REPORT_ENTRIES.map(async (r) => ({
        ...r,
        allowed: await mustRole(user, r.page),
      })))
    : [];
  const reportMatches = reportBranches
    .filter(r => r.allowed && (r.label.toLowerCase().includes(q.toLowerCase()) || r.description.toLowerCase().includes(q.toLowerCase())))
    .map(r => ({
      module: 'reports', id: r.key, title: r.label, subtitle: 'Report', description: r.description,
      status: null, created_at: null, route: SEARCH_MODULE_ROUTE.reports,
    }));

  if (!permitted.length && !reportMatches.length) {
    return { ok: true, total: reportMatches.length, moduleCounts: {}, results: reportMatches };
  }

  const params = [
    `%${q}%`,                                                     // $1
    wId,                                                          // $2
    filters.status || null,                                       // $3
    filters.department || null,                                   // $4
    filters.createdBy ? `%${filters.createdBy}%` : null,          // $5
    `${q}%`,                                                      // $6
    user.id,                                                      // $7
    user.role,                                                    // $8
    filters.fromDate || null,                                     // $9  (date range — applied once, outer level)
    filters.toDate || null,                                       // $10
  ];

  const page  = Math.max(0, Number(filters.page || 0));
  const limit = Math.min(50, Math.max(1, Number(filters.limit || 20)));
  const offset = page * limit;

  let results = [];
  let moduleCounts = {};
  let total = 0;

  if (permitted.length) {
    const unioned = permitted.map(m => `(${m.sql})`).join('\n      union all\n      ');
    const sortExpr = {
      newest:       'created_at desc nulls last, id desc',
      oldest:       'created_at asc nulls last, id desc',
      alphabetical: 'title asc',
      relevance:    "(case when unaccent(title) ilike unaccent($6) then 0 else 1 end) asc, created_at desc nulls last",
    }[filters.sort] || 'created_at desc nulls last, id desc';

    // Single CTE computes module_total/module_rank/grand_total once via window
    // functions (over the full permitted+filtered match set, before any paging),
    // then the outer SELECT applies mode-specific filtering/ordering/paging —
    // window function output can't be filtered in the same SELECT that defines it.
    //
    // Anchor clause: Postgres must infer a type for every "$N" up to the highest
    // one referenced anywhere in the statement. Depending on which modules are
    // permitted/selected and which sort is requested, some of $1-$8 may not
    // appear in any branch's SQL — leaving a "gap" Postgres can't type, which
    // fails with "could not determine data type of parameter $N" even though a
    // value was bound for it. This no-op clause references all eight explicitly
    // (with casts) so every position is always resolvable, regardless of mode.
    const anchor = `($1::text is null or true) and ($2::bigint is null or true)
      and ($3::text is null or true) and ($4::text is null or true)
      and ($5::text is null or true) and ($6::text is null or true)
      and ($7::bigint is null or true) and ($8::text is null or true)
      and ($9::date is null or true) and ($10::date is null or true)`;
    const dateRange = `($9::date is null or ranked.created_at::date >= $9::date)
      and ($10::date is null or ranked.created_at::date <= $10::date)`;
    const sql = `
      with ranked as (
        select x.*,
               count(*) over (partition by module)                                        as module_total,
               row_number() over (partition by module order by created_at desc nulls last) as module_rank,
               count(*) over ()                                                            as grand_total
        from (
          ${unioned}
        ) x
      )
      select * from ranked
      where ${anchor} and ${dateRange}
      ${moduleFilter ? '' : `and module_rank <= ${SEARCH_OVERVIEW_CAP}`}
      order by ${moduleFilter ? sortExpr : 'module asc, created_at desc nulls last'}
      ${moduleFilter ? 'limit $11 offset $12' : ''}`;
    const sqlParams = moduleFilter ? [...params, limit, offset] : params;

    const { rows } = await pool.query(sql, sqlParams);
    total = rows.length ? Number(rows[0].grand_total) : 0;
    for (const r of rows) moduleCounts[r.module] = Number(r.module_total);
    results = rows.map(({ module_total, module_rank, grand_total, ...r }) => ({
      ...r, route: SEARCH_MODULE_ROUTE[r.module] || null,
    }));

    // 'production' spans daily_logs from three different workshop types, each
    // with its own screen (Harvest/Timber/Poles) on both clients — there's no
    // single destination for the module as a whole, only per-row. Rather than
    // add a 9th UNION column to every other branch just for this one, resolve
    // it with one small follow-up lookup keyed by the ids already returned.
    const productionIds = results.filter((r) => r.module === 'production').map((r) => r.id);
    if (productionIds.length) {
      const { rows: typeRows } = await pool.query(
        `select dl.id, w.workshop_type
           from daily_logs dl
           left join warehouses w on w.id = dl.workshop_id
          where dl.id = any($1::int[])`,
        [productionIds],
      );
      const typeById = new Map(typeRows.map((r) => [r.id, r.workshop_type]));
      results = results.map((r) => (
        r.module === 'production' ? { ...r, workshop_type: typeById.get(r.id) ?? null } : r
      ));
    }
  }

  if (!moduleFilter || moduleFilter === 'reports') {
    results = results.concat(reportMatches);
    total += reportMatches.length;
    if (reportMatches.length) moduleCounts.reports = reportMatches.length;
  }

  return { ok: true, total, moduleCounts, results };
}

