// ── CEO Overview ──────────────────────────────────────────────────────────────

async function getCeoOverview(userId) {
  const user = await getUser(userId);
  // Master Professionalization Phase C2 — was a hardcoded ['admin','ceo']
  // role-array check, the same anti-pattern already fixed elsewhere in this
  // file (see machineCategoriesCreate's own comment on this exact class of
  // bug): a custom role granted the 'ceo' page via the per-user permission
  // checkbox (renderPermissionCheckboxes' chk('ceo', 'CEO Overview')) would
  // see the nav item and pass every client-side check, then be silently
  // denied here anyway because their literal user.role isn't 'admin'/'ceo'.
  // Confirmed safe: db/migrate.js already grants both 'admin' and 'ceo'
  // roles the 'ceo' page live (lines 138, 743), so this is a strict
  // widening-to-match-the-permission-system fix, not a behavior change for
  // either existing role.
  if (!(await mustRole(user, 'ceo'))) return { ok: false, error: 'Access denied' };

  const month = new Date().toISOString().slice(0, 7);
  const monthStart = `${month}-01`;
  const d = new Date();
  const monthLabel = d.toLocaleString('default', { month: 'long', year: 'numeric' });

  // Master Professionalization Phase C2 (Priority 2 — data correctness, and
  // Priority 13 — performance) — two real, evidenced issues in the original
  // 3 date-scoped queries below, fixed together since both are in the same
  // WHERE clause:
  // (1) None of the 3 filtered on deleted_at, unlike every other reader of
  //     these same tables (e.g. mv_stock_by_workshop's own
  //     `daily_logs where deleted_at is null`) — a soft-deleted daily log,
  //     harvest log, or a CANCELLED/soft-deleted sales order was still being
  //     counted into the CEO's "this month" totals, most materially for
  //     sales.revenue/sales.total_orders.
  // (2) `to_char(col,'YYYY-MM')=$1` can't use a plain index on log_date/
  //     harvest_date/created_at (full scan every load); executiveDashboard's
  //     sibling queries already use range predicates instead — matched here.
  const [prod, harvest, sales, mach, veh, cas, labour, chg, pendingPoles, pendingMonthly] = await Promise.all([
    pool.query(`
      select coalesce(sum(timber_units),0)::int  as timber_units,
             coalesce(sum(poles_units),0)::int   as poles_units,
             coalesce(sum(downtime_hours),0)::numeric as downtime_hours,
             count(*)::int                        as entries
      from daily_logs
      where log_date >= $1::date and log_date < ($1::date + interval '1 month')
        and deleted_at is null`, [monthStart]),

    pool.query(`
      select coalesce(sum(quantity),0)::int       as trees,
             coalesce(sum(logs_crosscut),0)::int  as logs
      from harvest_logs
      where harvest_date >= $1::date and harvest_date < ($1::date + interval '1 month')
        and deleted_at is null`, [monthStart]),

    pool.query(`
      select count(*)::int                                      as total_orders,
             coalesce(sum(quantity*unit_price),0)::numeric      as revenue
      from sales_orders
      where created_at >= $1::date and created_at < ($1::date + interval '1 month')
        and deleted_at is null`, [monthStart]),

    // Fleet & Equipment Phase 1 — 'In Use'/'Under Maintenance' were never the
    // literal values actually written (the real vocabulary is
    // Available/Running/Maintenance/Breakdown — confirmed against
    // renderMachines' own status dropdown); these two counters silently
    // read zero.
    pool.query(`
      select count(*)::int                                                 as total,
             count(*) filter (where status='Available')::int               as available,
             count(*) filter (where status='Running')::int                 as in_use,
             count(*) filter (where status in ('Maintenance','Breakdown'))::int as maintenance
      from machines where active=true`),

    pool.query(`select count(*)::int as total from vehicles where status='Active' and deleted_at is null`),

    pool.query(`select count(*)::int as total from casuals where active=true`),

    pool.query(`select count(*)::int as pending from casual_labour_requests where status='Pending'`),

    pool.query(`select count(*)::int as pending from change_requests where status='Pending'`),

    pool.query(`select count(*)::int as n from poles_purchase_requests where status='Pending'`),

    pool.query(`select approved from monthly_approvals where month_key=$1`, [month])
  ]);

  const prodRow        = prod.rows[0];
  const downtimeHours  = Number(prodRow.downtime_hours || 0);

  return {
    ok: true,
    month:    monthLabel,
    monthKey: month,
    production: {
      ...prodRow,
      downtime_hours:  downtimeHours,
      downtime_status: downtimeHours > 8 ? 'review_required' : 'within_target',
    },
    harvest:    harvest.rows[0],
    sales:      sales.rows[0],
    machines:   mach.rows[0],
    vehicles:   Number(veh.rows[0].total),
    casuals:    Number(cas.rows[0].total),
    pendingLabour:          Number(labour.rows[0].pending),
    pendingChanges:         Number(chg.rows[0].pending),
    pendingPolesRequests:   Number(pendingPoles.rows[0].n),
    pendingMonthlyApproval: !(pendingMonthly.rows[0]?.approved),
  };
}

