// ── Executive SRM Dashboard + Reports ────────────────────────────────────
async function srmExecutiveDashboard(userId) {
  const user = await getUser(userId);
  if (!(await mustRole(user, 'procurement-suppliers'))) return { ok: false, error: 'Access denied' };

  const [supplierCount, contractRows, complianceRows, docRows, planRows, commRows, intel] = await Promise.all([
    pool.query(`select count(*)::int as n from procurement_suppliers`),
    pool.query(`select status, end_date from procurement_supplier_contracts`),
    pool.query(`select supplier_id, compliance_type, status, expiry_date from supplier_compliance`),
    pool.query(`select count(*)::int as n from supplier_documents where status <> 'archived'
                and expiry_date is not null and expiry_date < current_date + interval '30 days'`),
    pool.query(`select status, completion_percent from supplier_improvement_plans`),
    pool.query(`select to_char(date_trunc('month', date), 'YYYY-MM') as month, count(*)::int as n
                from supplier_communications where date > now() - interval '6 months' group by 1 order by 1`),
    _supplierIntelRows(user, {}),
  ]);

  let active = 0, expiring = 0, expired = 0;
  const contractTimeline = [];
  for (const c of contractRows.rows) {
    if (c.status === 'renewed' || c.status === 'cancelled') continue;
    const s = _expiryStatus(c.end_date);
    if (s === 'expired') expired++; else if (s === 'expiring') expiring++; else active++;
    if (c.end_date) contractTimeline.push({ month: _ymFromDate(c.end_date), status: s });
  }

  const { rows: suppliersForCompliance } = await pool.query(`select id from procurement_suppliers where status <> 'archived'`);
  const totalExpected = suppliersForCompliance.length * SRM_COMPLIANCE_TYPES.length;
  const byKey = new Set(complianceRows.rows.map((r) => `${r.supplier_id}:${r.compliance_type}`));
  let validCount = 0;
  for (const s of suppliersForCompliance) {
    for (const type of SRM_COMPLIANCE_TYPES) {
      const row = complianceRows.rows.find((r) => r.supplier_id === s.id && r.compliance_type === type);
      if (row && (row.status === 'waived' || _expiryStatus(row.expiry_date) === 'active')) validCount++;
    }
  }
  const compliancePct = totalExpected > 0 ? Math.round((validCount / totalExpected) * 100) : 100;
  const missingDocuments = totalExpected - byKey.size;

  const openPlans = planRows.rows.filter((p) => !['closed', 'completed'].includes(p.status));
  const avgCompletion = openPlans.length ? Math.round(openPlans.reduce((s, p) => s + Number(p.completion_percent || 0), 0) / openPlans.length) : 0;

  const highRiskSuppliers = intel.filter((s) => s.tier === 'High Risk').length;

  // Monthly contract-timeline bucket (count active/expiring/expired ends per month)
  const timelineByMonth = {};
  for (const t of contractTimeline) { (timelineByMonth[t.month] ||= { month: t.month, active: 0, expiring: 0, expired: 0 })[t.status === 'active' ? 'active' : t.status]++; }

  return {
    ok: true,
    kpis: {
      totalSuppliers: supplierCount.rows[0].n,
      activeContracts: active,
      expiringContracts: expiring,
      expiredContracts: expired,
      compliancePct,
      missingDocuments: Math.max(0, missingDocuments),
      openImprovementPlans: openPlans.length,
      highRiskSuppliers,
    },
    contractTimeline: Object.values(timelineByMonth).sort((a, b) => a.month.localeCompare(b.month)),
    complianceTrend: SRM_COMPLIANCE_TYPES.map((type) => {
      const rowsOfType = complianceRows.rows.filter((r) => r.compliance_type === type);
      const validForType = rowsOfType.filter((r) => r.status === 'waived' || _expiryStatus(r.expiry_date) === 'active').length;
      return { type, validPct: suppliersForCompliance.length ? Math.round((validForType / suppliersForCompliance.length) * 100) : 0 };
    }),
    communicationActivity: commRows.rows,
    improvementProgress: { openCount: openPlans.length, avgCompletion, closedCount: planRows.rows.length - openPlans.length },
    documentsNearExpiry: docRows.rows[0].n,
  };
}

const SRM_REPORT_TYPES = [
  'contract_register', 'expiring_contracts', 'compliance_status', 'document_register',
  'communication_log', 'improvement_plans', 'executive_summary',
];

async function srmReport(userId, reportType, filters = {}) {
  const user = await getUser(userId);
  if (!(await mustRole(user, 'procurement-suppliers'))) return { ok: false, error: 'Access denied' };
  if (!SRM_REPORT_TYPES.includes(reportType)) return { ok: false, error: 'Unknown report type' };

  switch (reportType) {
    case 'contract_register': {
      const r = await procurementContractsRegister(userId, filters);
      return { ok: true, reportType, rows: r.rows };
    }
    case 'expiring_contracts': {
      const r = await procurementContractsRegister(userId, filters);
      return { ok: true, reportType, rows: r.rows.filter((c) => c.computedStatus === 'expiring') };
    }
    case 'compliance_status': {
      const r = await supplierComplianceRegister(userId, filters);
      return { ok: true, reportType, rows: r.rows };
    }
    case 'document_register': {
      const r = await supplierDocumentsRegister(userId, filters);
      return { ok: true, reportType, rows: r.rows };
    }
    case 'communication_log': {
      const r = await supplierCommunicationsRegister(userId, filters);
      return { ok: true, reportType, rows: r.rows };
    }
    case 'improvement_plans': {
      const r = await supplierImprovementPlansRegister(userId, filters);
      return { ok: true, reportType, rows: r.rows };
    }
    case 'executive_summary': {
      const dash = await srmExecutiveDashboard(userId);
      return { ok: true, reportType, summary: dash };
    }
  }
}


